"""Write complete exploratory report from checked paired reductions."""
import json
from pathlib import Path
root=Path(__file__).resolve().parent;r=json.loads((root/'results.json').read_text());arms=r['arms'];est=r['estimates'];dif=r['paired_contrasts']
def pct(value):return 'unavailable' if value is None else f'{value*100:.2f}%'
def interval(ci,scale=100):return 'unavailable' if ci is None else f'[{ci[0]*scale:.2f}, {ci[1]*scale:.2f}]'
def metric(arm,name):return est[arm].get(name,{}).get('value')
selection=r['selection'];loss_results=[]
for arm in arms[1:]:
 value=dif[arm]['game_loss_fraction'];ci=value['ci95'];interpretation='fewer losses' if ci[1]<0 else 'more losses' if ci[0]>0 else 'loss difference uncertain (interval includes zero)'
 loss_results.append(f'{arm}: {interpretation}')
lines=['# d27 tempo exploration — 2026-10-09','','**Exploration lane. Non-confirmatory, no pre-registration, no eval/heldout data. Research guidance only.**','',f'1,000 paired fresh seeds per arm; {len(arms)*1000:,} terminal games in the primary comparison. Five decks, all 25 matchups, three scripted opponents, alternating seats, d=27. Same fixed-work fair S6 ledger/A/B harness.','', '**Measured outcome:** '+ '; '.join(loss_results)+'. Pointwise paired bootstrap intervals are exploratory and unadjusted for the parameter/arm search.','', '**The 200 ms budget is '+('met' if r['required_latency_budget_met'] else 'not met')+' in this fixed-work experiment.** Latency includes public observation, belief update, candidate generation, root reconstruction, scoring and command submission. Active wall time excludes explicit guard pauses; raw wall time includes them. CPU time is reported separately and is not a wall-time guarantee.','','| Arm | Wins / losses / draws | Win rate, 95% CI | Loss rate, 95% CI | Paired loss change vs baseline, pp |','|---|---:|---:|---:|---:|']
for arm in arms:
 o=r['outcomes'][arm];win=est[arm]['game_win_fraction'];loss=est[arm]['game_loss_fraction'];delta='—' if arm=='0' else f"{dif[arm]['game_loss_fraction']['difference']*100:+.2f} {interval(dif[arm]['game_loss_fraction']['ci95'])}"
 lines.append(f"| {arm} | {o['wins']} / {o['losses']} / {o['draws']} | {pct(win['value'])} {interval(win['ci95'])} | {pct(loss['value'])} {interval(loss['ci95'])} | {delta} |")
lines+=['','W had fewer fresh reporting losses than the separately selected EW combination (7 versus 17). The E-only result is uncertain, and adding E to W did not improve the observed point estimate. Under-4 arrivals remained well above the 16–19% human reference even with W.', '', 'Win, loss and draw estimates and paired CIs are all in [results.json](results.json). Bootstrap: 2,000 shared seed resamples, paired across every arm and metric; event rates pool numerator and denominator counts. Zero empirical rates and [0,0] intervals do not establish population upper bounds.','','## Arm definitions and separate tuning','',f"0 is the original planner, horizon 160 ticks (8 s). E adds an own-elixir leaf option value with selected weight **{selection['elixir_weight']}**. H12/H16 use 240/320 ticks (12/16 s). W adds explicit 10/20/40-tick WAIT candidates and a calibrated prior with selected weight **{selection['wait_prior']}**. The selected combination is **{selection['combination_arm']}**, using the selected horizon **{selection['combo_horizon']/20:g} s** when it contains H.",'', 'The E option curve is nonnegative and concave: marginal value 1 below 4 elixir, 0.5 from 4 to 7, then −5.5/3 from 7 to 10. It is zero at 0 and 10 and positive in between. This rewards banked options, with diminishing marginal value and no full-cap bonus. The existing baseline elixir term remains present; terminal win/loss scores are unchanged. Only simulated own HUD elixir enters this extra term.','', 'The W prior adds `weight × sqrt(wait_seconds) × (1 − own_elixir/10)` to WAIT root scores. It vanishes at full cap. Waiting suppresses own scripted follow-ups for the chosen duration inside rollouts and suppresses physical player decisions for the same duration; opponent behavior continues. It preserves all original immediate-play candidates and original RNG draws. The 0.5 s explicit wait has the same follow-up timing as baseline WAIT; the useful additional durations are 1 and 2 s.','', 'Weights are selected from E={0.005,0.02} and W={0.0025,0.01}, plus H={12,16 s}, on 150 separate tuning seeds. Selection minimizes loss count, with ties preferring lower weights/shorter horizons. A second 150-seed block chooses among EH, EW, HW and EHW using the selected weights/horizon; ties use the fixed EW/EH/HW/EHW order. Reporting outcomes do not enter either selection.','', '| Tuning arm | Losses / 150 |','|---|---:|']
for arm,count in selection['tuning']['losses'].items():lines.append(f'| {arm} | {int(count)} |')
lines+=['','| Combination selection arm | Losses / 150 |','|---|---:|']
for arm,count in selection['combination_tuning']['losses'].items():lines.append(f'| {arm} | {int(count)} |')
lines+=['','## Loss-review metrics','','| Metric | '+' | '.join(arms)+' |','|---|'+'---:|'*len(arms)]
metrics=['arrival_under4_fraction','defender_not_in_hand_fraction','no_affordable_defender_in_hand_fraction']+ [m for m in est['0'] if 'cap' in m or 'leaked' in m or 'time_at_max' in m]+['card_per_deck_minute:'+n for n in ('Xbow','Giant','Rocket','Fireball','Log')]
for m in metrics:
 if m not in est['0']:continue
 percent=m.endswith('fraction');values=[pct(metric(k,m)) if percent else f'{metric(k,m):.4f}' for k in arms]
 lines.append('| '+m+' | '+' | '.join(values)+' |')
lines+=['','Defender availability uses the existing generic non-spell, non-win-condition hand proxy. Accepted card-play rates are per minute in games containing that card, including zero-use games. Cap leakage is the ledger’s conservative lower bound based on intervals already at full cap; it omits partial approaches to cap and collector overflow. All event counts, exposures and paired CIs are in the JSON.','','| Arm / expensive card | Hand opportunities | Affordable, 95% CI | Accepted plays / deck-minute, 95% CI | Selected / offered |','|---|---:|---:|---:|---:|']
for arm in arms:
 for card in ('Xbow','Giant','Rocket','Fireball'):
  affinity=est[arm]['affordable_hand_fraction:'+card];play=est[arm]['card_per_deck_minute:'+card];attr=r['attrition'][arm].get(card,{})
  lines.append(f"| {arm} / {card} | {int(affinity['denominator'])} | {pct(affinity['value'])} {interval(affinity['ci95'])} | {play['value']:.4f} {interval(play['ci95'],1)} | {attr.get('selected',0)} / {attr.get('scored_opportunities',0)} |")
lines+=['','Candidate attrition counts remain available, including masked, generator absent, reduction absent and final absent. Affordability is measured at search decision opportunities, not every telemetry frame; long WAIT choices reduce the number of opportunities. Consequently this metric is treatment-dependent and must be read alongside arrival metrics and accepted play rates.','','## Decision latency','','| Arm | Active-wall p50 / p95 / p99, ms | Raw-wall decisions >200 ms | CPU p50 / p95, ms | Raw-wall p95, ms |','|---|---:|---:|---:|---:|']
for arm in arms:
 l=r['latency'][arm];w=l['active_wall'];c=l['process_cpu']
 lines.append(f"| {arm} | {w['p50_ms']:.1f} / {w['p95_ms']:.1f} / {w['p99_ms']:.1f} | {pct(l['raw_wall']['over200_fraction'])} | {c['p50_ms']:.1f} / {c['p95_ms']:.1f} | {l['raw_wall']['p95_ms']:.1f} |")
lines+=['','| Horizon arm | Paired mean CPU latency change vs 0, ms (95% CI) | Paired mean active-wall change, ms (95% CI) | Paired mean raw-wall change, ms (95% CI) |','|---|---:|---:|---:|']
for arm in ('H12','H16'):
 c=dif[arm]['mean_cpu_decision_ms'];w=dif[arm]['mean_active_wall_decision_ms'];raw=dif[arm]['mean_raw_wall_decision_ms'];lines.append(f"| {arm} | {c['difference']:+.2f} {interval(c['ci95'],1)} | {w['difference']:+.2f} {interval(w['ci95'],1)} | {raw['difference']:+.2f} {interval(raw['ci95'],1)} |")
lines+=['','These timings come from loaded, idle-scheduled compute lanes. CPU timings help separate compute from descheduling, but hardware, SMT contention and GPU co-location differ across hosts. This is fixed-work search research, not approval to deploy a live player.','','## Seed exclusion and fair-information boundary','', 'Reporting uses `2**48 + 70_000 + i`, **i=10..1009**. Offsets 0..4 were in the prior A/B pause-parity registration, and offsets 5/6 would collide through helper seeds; offsets 7..9 are conservatively skipped. Tuning is `2**48 + 80_000 + i`; combination selection is `2**48 + 85_000 + i`, i=0..149. Smoke uses `+87_000`, two seeds. All game/shuffle/player seeds with helper offsets 0,100000,100001,100002 were checked against gate seed-only audit lists, historical exclusions, the loss-review ledger and every prior search A/B set. [Seed audit](seed-audit.json) includes source hashes and zero intersections.','', 'The player receives public observations, own HUD, accepted enemy events and independent sampled hidden-state beliefs. No live opponent hand, cycle or live RNG enters its search. Telemetry is reduced outside the player boundary. Perception coexistence instrumentation counts completion-journal records only; it does not decode predictions, labels or outcomes. No gate outcomes or evaluation payloads are used.','', 'For exact-harness comparability, opponent scripts retain immediate execution and immediate rollout answers. The command-delay review identifies this asymmetry as a realism limitation; these results do not resolve it. No command-delay/queued-command fix is mixed into these arms.','','## Compute and validation','', 'Shard payloads, short remote helpers, rsync servers and worker subprocesses start with `nice -n 10 chrt --idle 0`; forked workers inherit the settings. This explicit exec policy was applied at ~02:25Z after the coordinator detected a transient nice-0 process. Already-compliant shards were left running. First-interpreter-instruction, nested exec, fork-worker and fleet policy checks passed, with receipts under `receipts/`. HW was also corrected to exclude E, and its separate tuning games were rerun; the zero-loss EW winner was unchanged by this correction.', '', 'The simulation uses the existing A/B shard runner and improved throughput guard: SCHED_IDLE, core pinning, periodic exclusion of observed GPU/feeder cores and SMT siblings, and pauses only when the co-located GPU job’s measured interval rate falls below 95% of its separately measured baseline. GPU utilization does not control pausing. Captures use counts of the GPU job’s own completed-frame journals; 16 uses T11’s existing own interval-row throughput. Initial capture baselines were measured with this task’s simulations absent. Refreshed baselines retain verified unloaded control intervals and the originals; a failed control check never authorizes a refresh. Unknown/stale metrics and absent jobs are exempt. The whole-worker process declaration includes supervisors for lease admission.','', '04: ≤40 simultaneous simulation workers. 03: reservation absence checked before launch, ≤96 workers, CPUs 0–47 and 64–111. Leased 09/13/14/15: ≤20 workers each; 16: ≤40. Wrapper v2 r3 handles combined admission and refusal; no cap bypass. New leased shards stop at 04:15Z and runtime termination begins by 04:29Z for exit by 04:30Z. Already-paused leased shards with stalled progress can drain after five minutes and resume their exact uncompleted cases elsewhere; the scheduler retains completed games and retires that lane for the phase. No work on 01/02/08, no git commits, no broad process kills, no tailscale/crontab, no owner-repository access.','']
if (root/'compute-audit.json').exists():
 audit=json.loads((root/'compute-audit.json').read_text());lines.append(f"Completed unique simulations: **{audit['completed_unique_games']:,}**; completed-game CPU lower bound: **{audit['completed_worker_cpu_seconds']/3600:.2f} core-hours**. Initialization, reducers, monitors and unfinished attempts are excluded from this CPU total. The compute audit separately counts the 150 superseded HW instances and their CPU cost. Admission refusals and per-attempt wall time are retained in the compute audit.")
 lines += ['', '| Host | Unique games | Completed CPU, s | Worker-time utilization lower bound | Measured GPU-rate samples / all guard samples |', '|---|---:|---:|---:|---:|']
 for host,row in sorted(audit['per_host'].items()):
  u=row.get('completed_cpu_over_declared_worker_wall_lower_bound');lines.append(f"| {host} | {row['games']} | {row['worker_cpu_seconds']:.1f} | {pct(u)} | {row['measured_guard_samples']} / {row['guard_samples']} |")
 lines += ['', 'The utilization lower bound divides completed unique game CPU by declared workers × attempt wall time, including startup and guard pauses. It is not measured hardware occupancy. Unknown/stale GPU rates are explicitly exempt; a lane with missing rate samples does not establish validated throughput protection. The per-host guard counts deduplicate resumed histories.']
lines+=['','All leased wrapped jobs and this task’s leased monitors were verified exited by ~02:45Z, with no remaining own leased runtime or monitor processes. The final home shard completed normally on04 at ~02:51Z. Its requested SIGINT migration did not terminate the runtime; no forced tree cleanup or migration occurred. Future runners explicitly install SIGINT/SIGTERM cleanup handlers.', '', 'The first full 600 s on 03 completed 748 games (1.247 games/s). The runner reuses warmed external bytecode, assigns horizon-aware LPT case costs, and uses 50-seed reporting shards to amortize resource initialization. Throughput interruptions and unloaded refresh controls are retained in the receipts.', '', '[Tests](receipts/tests.txt), [default/disabled-tempo action parity](receipts/parity.json), [runtime hashes](receipts/runtime-pin.json), [compute audit](compute-audit.json), [first-ten-minute throughput](receipts/first10-throughput.json), and scheduler/wrapper receipts under `receipts/`. Full per-game reductions remain on 04 and shard copies on their original hosts. Compact results and receipts are copied to 05.','','## What to try next','', '1. Split W into timed waits without the prior and the calibrated prior without extra durations, on new exploration seeds. The current W arm bundles both, so its result does not identify which component helps. Inspect WAIT root scores and the behavior at submission and execution.','2. If E is null or worse, test persistent banked-option value across the rollout rather than only at a leaf whose scripted follow-up policy spends immediately. Repeat the most promising intervention with delay matched on both sides, keeping that comparison separate from this exact-harness screen.','3. Establish a wall-deadline implementation that retains play/WAIT coverage before any live test. Longer horizons increase fixed-work cost; CPU budgets do not enforce the 200 ms wall requirement.','', 'Behavioral resemblance to humans is a diagnostic, not a reward target or causal proof of improved play. Null results are reported as nulls; tuning improvements are not assumed to transport to fresh seeds.']
(root/'RESULTS.md').write_text('\n'.join(lines)+'\n')
